import { BOX_SIZE, SUDOKU_SIZE } from '@sudoku/constants';
import { decodeSencode, encodeSudoku } from '@sudoku/sencode';
import { generateSudoku } from '@sudoku/sudoku'; // 删除了 solveSudoku
import { derived, writable } from 'svelte/store';
import { hints } from './hints';
import { createGame, createSudoku } from '../../../domain';

// 新增一个可写 store，用于告诉 UI 当前是否处于探索模式
export const exploreStore = writable(false);

function createGrid() {
	let currentGame = null;
	const { subscribe, set } = writable(
		Array(9).fill().map(() => Array(9).fill(0))
	);

    // 辅助函数：同步 UI 状态
    const syncState = () => {
        if (currentGame) {
            set(currentGame.getSudoku().getGrid());
            exploreStore.set(currentGame.isExploring);
        }
    };

	return {
		subscribe,

		generate(difficulty) {
			const initialGrid = generateSudoku(difficulty);
			const sudoku = createSudoku(initialGrid);
			currentGame = createGame({sudoku})
			syncState();
		},

		decodeSencode(sencode) {
			const initialGrid = decodeSencode(sencode);
			const sudoku = createSudoku(initialGrid);
			currentGame = createGame({sudoku});
			syncState();
		},

		get(gridStore, x, y) {
			return gridStore[y][x];
		},

		getSencode(gridStore) {
			return encodeSudoku(gridStore);
		},
        
		isGiven(x, y) {
			if (!currentGame) return false;
			const sudoku = currentGame.getSudoku();
			return sudoku.isGiven ? sudoku.isGiven(y, x) : false; // 注意 y 是 row, x 是 col
		},
		
		makeMove(x, y, value) {
			if (!currentGame) return false;
			
			const move = { row: y, col: x, value };
			const success = currentGame.guess(move);
			
			if (success) syncState();
			
			return success;
		},

		undo() {
			if (!currentGame) return false;
			const success = currentGame.undo();
            if(success) syncState();
			return success;
		},

		redo() {
			if (!currentGame) return false;
			const success = currentGame.redo();
            if(success) syncState();
			return success;
		},

		canUndo() {
			return currentGame ? currentGame.canUndo() : false;
		},

		canRedo() {
			return currentGame ? currentGame.canRedo() : false;
		},

        // ========== 新增：合规的 Hint 接口 ==========

		applyHint() {
			if(!currentGame) return false;
            // 通过 Domain 获取唯一推定值
            const hint = currentGame.getNextHint();
            if (!hint) return false; // 没有唯一解，暗示该进入探索模式了

			const success = currentGame.guess(hint);
			if(success) {
				syncState();
			}
			return success;
		},

        getCandidates(x, y) {
            if(!currentGame) return [];
            return currentGame.getCandidates(y, x); // y 是 row, x 是 col
        },

        // ========== 新增：探索模式接口 ==========
        
        startExplore() {
            if (!currentGame) return false;
            const success = currentGame.startExplore();
            if(success) syncState();
            return success;
        },

        commitExplore() {
            if (!currentGame) return false;
            const success = currentGame.commitExplore();
            if(success) syncState();
            return success;
        },

        rollbackExplore() {
            if (!currentGame) return false;
            const success = currentGame.rollbackExplore();
            if(success) syncState();
            return success;
        }
	};
}

export const grid = createGrid();

function createUserGrid() {
	const userGrid = writable(Array(9).fill().map(() => Array(9).fill(0)));

	grid.subscribe($grid => {
		let newGrid = [];
		for (let y = 0; y < SUDOKU_SIZE; y++) {
			newGrid[y] = [];
			for (let x = 0; x < SUDOKU_SIZE; x++) {
				newGrid[y][x] = $grid[y][x];
			}
		}
		userGrid.set(newGrid);
	});

	return {
		subscribe: userGrid.subscribe,
		
		set: (pos, value) => {
			if (value !== 0 && (typeof value !== 'number' || !Number.isInteger(value) || value < 1 || value > 9)) {
				return;
			}
			// 修复：必须让 Domain 先尝试，成功了组件 UI 才会因为 subscribe 自动刷新。
            // 不再先改 userGrid 再改 domain，保证单一数据源！
			grid.makeMove(pos.x, pos.y, value);
		},

		applyHint: () => {
			hints.useHint();
			grid.applyHint(); 
		},
	};
}

export const userGrid = createUserGrid();

// 冲突格逻辑不变
export const invalidCells = derived(userGrid, $userGrid => {
	const _invalidCells = [];

	const addInvalid = (x, y) => {
		const xy = x + ',' + y;
		if (!_invalidCells.includes(xy)) _invalidCells.push(xy);
	};

	for (let y = 0; y < SUDOKU_SIZE; y++) {
		for (let x = 0; x < SUDOKU_SIZE; x++) {
			const value = $userGrid[y][x];
			if (value) {
				for (let i = 0; i < SUDOKU_SIZE; i++) {
					if (i !== x && $userGrid[y][i] === value) addInvalid(x, y);
					if (i !== y && $userGrid[i][x] === value) addInvalid(x, i);
				}
				const startY = Math.floor(y / BOX_SIZE) * BOX_SIZE;
				const endY = startY + BOX_SIZE;
				const startX = Math.floor(x / BOX_SIZE) * BOX_SIZE;
				const endX = startX + BOX_SIZE;
				for (let row = startY; row < endY; row++) {
					for (let col = startX; col < endX; col++) {
						if (row !== y && col !== x && $userGrid[row][col] === value) {
							addInvalid(col, row);
						}
					}
				}
			}
		}
	}
	return _invalidCells;
}, []);